<div class="card">
  <div class="card-body">
    <h1 class="h4">Elektro-Prüfungen importieren</h1>
    <?php if (!empty($cron['healthy'])): ?><div class="alert alert-success py-2">Cron letzter Lauf: <?= htmlspecialchars((string) $cron['last_run']) ?></div><?php else: ?><div class="alert alert-warning py-2">Warnung: Der Phoenix-Cron wurde seit mehr als 5 Minuten nicht ausgeführt<?= !empty($cron['last_run']) ? ' (letzter Lauf: ' . htmlspecialchars((string) $cron['last_run']) . ')' : '' ?>.</div><?php endif; ?>
    <?php if (!empty($pendingMeasurementsByDate)): ?><details class="mb-3" open><summary><strong>Messdaten noch importieren</strong> (<?= array_sum(array_map('count', $pendingMeasurementsByDate)) ?> Prüfungen)</summary><div class="small text-body-secondary mt-2">Für diese manuellen Prüfungen fehlen noch Messwerte. Nach dem Import werden die Prüfungen automatisch vervollständigt.</div><?php foreach ($pendingMeasurementsByDate as $pendingDate => $pendingRows): ?><h3 class="h6 mt-3">Prüfdatum <?= htmlspecialchars((string) $pendingDate) ?></h3><div class="table-responsive"><table class="table table-sm align-middle"><thead><tr><th>Prüfung</th><th>Gerät</th><th>Speicherplatz</th><th></th></tr></thead><tbody><?php foreach ($pendingRows as $pending): ?><tr><td><a href="<?= htmlspecialchars(url_for('admin/pruefungen/' . (int) $pending['inspection_id']), ENT_QUOTES) ?>"><?= htmlspecialchars((string) ($pending['inspection_number'] ?: '—')) ?></a></td><td><a href="<?= htmlspecialchars(url_for('geraete?device_id=' . (int) $pending['device_id']), ENT_QUOTES) ?>"><?= htmlspecialchars(trim((string) $pending['number'] . ' · ' . (string) $pending['name'])) ?></a></td><td><?= htmlspecialchars((string) ($pending['storage_slot'] ?: '—')) ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= htmlspecialchars(url_for('admin/pruefungen/' . (int) $pending['inspection_id'] . '/bearbeiten'), ENT_QUOTES) ?>">Prüfung öffnen</a></td></tr><?php endforeach; ?></tbody></table></div><?php endforeach; ?></details><?php endif; ?>
    <?php if (!empty($jobs)): ?><details class="mb-3" open><summary><strong>Import-Jobs</strong> (<?= count($jobs) ?>)</summary><div class="table-responsive mt-2"><table class="table table-sm"><thead><tr><th>ID</th><th>Status</th><th>Kunde</th><th>Fortschritt</th><th>Gerät</th><th>Details</th><th></th></tr></thead><tbody><?php foreach ($jobs as $job): $jobId=(string)($job['id']??''); $jobRunning=in_array(($job['state']??''), ['queued','running'], true); ?><tr data-phoenix-job="<?= htmlspecialchars($jobId, ENT_QUOTES) ?>"><td><a href="<?= htmlspecialchars(url_for('admin/pruefungen/import?phoenix_job=' . rawurlencode($jobId)), ENT_QUOTES) ?>" title="Job öffnen"><?= htmlspecialchars($jobId) ?></a></td><td class="job-state"><?= htmlspecialchars((string) ($job['state'] ?? '')) ?></td><td><?= htmlspecialchars((string) ($job['customer_id'] ?? '')) ?></td><td class="job-progress"><?php if (($job['total'] ?? 0) > 0): ?><?= (int) ($job['step'] ?? 0) ?> / <?= (int) $job['total'] ?><?php else: ?>—<?php endif; ?></td><td class="job-device"><?= htmlspecialchars((string) ($job['current_device'] ?? '')) ?></td><td><details<?= $jobRunning ? ' open' : '' ?>><summary>anzeigen</summary><div class="small text-body-secondary job-message"><?= htmlspecialchars((string) ($job['message'] ?? '')) ?></div><pre class="small mb-0 job-details"><?= htmlspecialchars((string) json_encode($job['stats'] ?? ($job['error'] ?? ''), JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE)) ?></pre></details></td><td><?php if ($jobRunning): ?><form method="post" action="<?= htmlspecialchars(url_for('admin/pruefungen/import/' . rawurlencode($jobId) . '/abbrechen'), ENT_QUOTES) ?>" onsubmit="return confirm('Diesen Import wirklich abbrechen? Bereits importierte Datensätze bleiben erhalten.');"><button class="btn btn-sm btn-outline-danger">Abbrechen</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></details><?php endif; ?>
    <?php if (!empty($importLogs)): ?><details class="mb-3"><summary><strong>Letzte Importe</strong> (<?= count($importLogs) ?>)</summary><div class="mt-2"><?php foreach ($importLogs as $log): $logStats=$log['stats']??[]; ?><details class="border rounded p-2 mb-2"><summary><?= htmlspecialchars((string) ($log['type'] ?? 'Import')) ?> · <?= htmlspecialchars((string) ($log['created_at'] ?? '')) ?> · <?= (int) ($logStats['imported'] ?? 0) ?> Prüfungen</summary><div class="small mt-2">Neu: <?= (int) ($logStats['devices'] ?? 0) ?> Geräte · Aktualisiert: <?= (int) ($logStats['updated'] ?? 0) ?> Prüfungen · Übersprungen: <?= (int) ($logStats['skipped'] ?? 0) ?></div><?php foreach (['new_devices' => 'Neue Geräte', 'updated_devices' => 'Aktualisierte Geräte'] as $listKey => $listLabel): if (!empty($logStats[$listKey])): ?><div class="small mt-2"><strong><?= $listLabel ?>:</strong> <?php foreach ($logStats[$listKey] as $device): ?><a class="me-2" href="<?= htmlspecialchars(url_for('geraete?device_id=' . (int) $device['id']), ENT_QUOTES) ?>"><?= htmlspecialchars((string) ($device['number'] ?? '')) ?></a><?php endforeach; ?></div><?php endif; endforeach; ?><details class="mt-2"><summary>Debug-Log anzeigen</summary><pre class="small mb-0 mt-2"><?= htmlspecialchars((string) json_encode($logStats, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE)) ?></pre></details></details><?php endforeach; ?></div></details><?php endif; ?>
    <p class="text-body-secondary">Importe aus JSON/JSONL, CSV/ODS und Phoenix werden hier zentral verarbeitet. Das Verzeichnis kann sowohl ältere JSON/JSONL-Dateien als auch CSV/ODS-Paare enthalten. Detailausgaben stehen nur noch im Debug-Bereich.</p>
    <?php if (is_array($stats)): ?><div class="row g-2 mb-3"><?php foreach (['files' => 'Dateien', 'imported' => 'Prüfungen neu', 'updated' => 'Prüfungen aktualisiert', 'devices' => 'Geräte neu', 'reports' => 'Berichte', 'skipped' => 'Übersprungen'] as $key => $label): ?><div class="col-6 col-md-2"><div class="border rounded p-2 text-center"><div class="small text-body-secondary"><?= $label ?></div><strong><?= (int) ($stats[$key] ?? 0) ?></strong></div></div><?php endforeach; ?></div><details class="mb-3"><summary>Debug-Output anzeigen</summary><pre class="small mt-2"><?= htmlspecialchars((string) json_encode($stats, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE)) ?></pre></details><?php endif; ?>
    <?php if ($message !== null): ?><div class="alert alert-info"><?= htmlspecialchars($message) ?></div><?php endif; ?>
    <form method="post" class="row g-2">
      <input type="hidden" name="action" value="directory_import_job">
      <div class="col-md-6"><label class="form-label" for="directory">Importverzeichnis</label><input class="form-control" id="directory" name="directory" required placeholder="/home/codexuser/Elektro-Testdaten"><div class="form-text">JSON/JSONL-Dateien und CSV/ODS-Paare.</div></div><div class="col-md-6"><label class="form-label" for="reports_directory">PDF-Quellverzeichnis (optional)</label><input class="form-control" id="reports_directory" name="reports_directory" placeholder="/var/www/berichte"><div class="form-text">PDF-Dateien werden über die führende Prüfnummer zugeordnet.</div></div>
