      <div class="col-md-4"><label class="form-label" for="default_examiner">Prüfer für fehlende Angaben</label><select class="form-select" id="default_examiner" name="default_examiner"><option value="">Bitte wählen</option><?php foreach (($examinerUsers ?? []) as $examinerUser): ?><option value="<?= htmlspecialchars((string) $examinerUser['value'], ENT_QUOTES) ?>"><?= htmlspecialchars((string) $examinerUser['label']) ?></option><?php endforeach; ?></select></div>
      <div class="col-md-4"><label class="form-label" for="default_next_due_offset_days">Tage bis zur nächsten Prüfung</label><div class="input-group"><input class="form-control" id="default_next_due_offset_days" name="default_next_due_offset_days" type="number" min="1" step="1" placeholder="z. B. 365"><button class="btn btn-outline-secondary" type="button" onclick="setNextAudit(365)">365 Tage</button><button class="btn btn-outline-secondary" type="button" onclick="setNextAudit(730)">730 Tage</button></div><div class="form-text">Wird relativ zum jeweiligen Prüfdatum berechnet.</div></div>
      <div class="col-12"><button class="btn btn-primary">Paar importieren</button></div>
      <div class="col-12 mt-3"><label class="form-label">Regeln für Raum/Gerät</label><div id="import-rules"><div class="row g-2 import-rule mb-2"><div class="col-md-2"><input class="form-control rule-room" placeholder="Raum, z. B. K203"></div><div class="col-md-2"><input class="form-control rule-device" placeholder="Gerät/Bezeichnung"></div><div class="col-md-2"><input class="form-control rule-number" placeholder="Gerätenummer (optional)"></div><div class="col-md-2"><input class="form-control rule-type" placeholder="Prüfart"></div><div class="col-md-2"><select class="form-select rule-examiner"><option value="">Prüfer</option><?php foreach (($examinerUsers ?? []) as $examinerUser): ?><option value="<?= htmlspecialchars((string) $examinerUser['value'], ENT_QUOTES) ?>"><?= htmlspecialchars((string) $examinerUser['label']) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><input class="form-control rule-days" type="number" min="1" step="1" placeholder="Tage"></div></div></div><input type="hidden" name="import_rules" id="import_rules"><button class="btn btn-sm btn-outline-secondary" type="button" onclick="addImportRule()">Weitere Regel</button><div class="form-text">Die spezifischste Regel gewinnt: Gerätenummer vor Gerät vor Raum vor globalem Fallback.</div></div>
    </form>
    <hr>
    <h2 class="h6">Phoenix-Einweg-Sync (nur neue Geräte)</h2>
    <p class="text-body-secondary">Lädt Prüfungen eines Phoenix-Kunden über die API und übernimmt ausschließlich Gerätenummern, die lokal noch nicht existieren. Der Bearer-Token wird nicht gespeichert.</p>
    <form method="post" class="row g-2">
      <input type="hidden" name="action" value="phoenix_sync">
      <div class="col-md-3"><label class="form-label" for="phoenix_customer_id">Phoenix-Kunden-ID</label><input class="form-control" id="phoenix_customer_id" name="phoenix_customer_id" inputmode="numeric" required></div>
      <div class="col-md-5"><label class="form-label" for="phoenix_token">Bearer-Token</label><input class="form-control" id="phoenix_token" name="phoenix_token" type="password" autocomplete="off" required></div>
      <div class="col-md-4"><label class="form-label" for="phoenix_api_url">API-URL</label><input class="form-control" id="phoenix_api_url" name="phoenix_api_url" value="https://api.phoenix-arbeitswelt.de/phoenix"></div>
      <div class="col-12"><button class="btn btn-outline-primary">Neue Phoenix-Geräte synchronisieren</button></div>
    </form>
    <?php if (is_array($stats) && !empty($stats['new_devices'])): ?><details class="mt-3"><summary>Neu angelegte Geräte (<?= count($stats['new_devices']) ?>)</summary><ul class="mt-2"><?php foreach ($stats['new_devices'] as $newDevice): ?><li><a href="<?= htmlspecialchars(url_for('geraete?device_id=' . (int) $newDevice['id']), ENT_QUOTES) ?>"><?= htmlspecialchars((string) $newDevice['number']) ?> · <?= htmlspecialchars((string) $newDevice['name']) ?></a></li><?php endforeach; ?></ul></details><?php endif; ?>
    <?php if (is_array($stats) && !empty($stats['updated_devices'])): ?><details class="mt-3"><summary>Aktualisierte Geräte (<?= count($stats['updated_devices']) ?>)</summary><ul class="mt-2"><?php foreach ($stats['updated_devices'] as $updatedDevice): ?><li><a href="<?= htmlspecialchars(url_for('geraete?device_id=' . (int) $updatedDevice['id']), ENT_QUOTES) ?>"><?= htmlspecialchars((string) $updatedDevice['number']) ?> · <?= htmlspecialchars((string) $updatedDevice['name']) ?></a></li><?php endforeach; ?></ul></details><?php endif; ?>
    <?php if (is_array($stats) && !empty($stats['not_imported'])): ?><details class="mt-3"><summary>Nicht importiert (<?= count($stats['not_imported']) ?>)</summary><div class="table-responsive mt-2"><table class="table table-sm"><thead><tr><th>Speicherplatz</th><th>Quelle</th><th>Grund</th></tr></thead><tbody><?php foreach ($stats['not_imported'] as $entry): ?><tr><td><?= htmlspecialchars((string) ($entry['storage_slot'] ?? '')) ?></td><td><?= htmlspecialchars((string) ($entry['source'] ?? '')) ?></td><td><?= htmlspecialchars((string) ($entry['reason'] ?? '')) ?></td></tr><?php endforeach; ?></tbody></table></div></details><?php endif; ?>
  </div>
</div>
<script>window.setNextAudit=function(days){document.getElementById('default_next_due_offset_days').value=days;};window.addImportRule=function(){const first=document.querySelector('.import-rule');const clone=first.cloneNode(true);clone.querySelectorAll('input').forEach(i=>i.value='');clone.querySelectorAll('select').forEach(s=>s.selectedIndex=0);document.getElementById('import-rules').appendChild(clone);};document.querySelectorAll('form[enctype="multipart/form-data"]').forEach(f=>f.addEventListener('submit',function(){const rules=[];document.querySelectorAll('.import-rule').forEach(r=>rules.push({room:r.querySelector('.rule-room').value,device:r.querySelector('.rule-device').value,number:r.querySelector('.rule-number').value,inspection_type:r.querySelector('.rule-type').value,examiner:r.querySelector('.rule-examiner').value,next_due_offset_days:r.querySelector('.rule-days').value}));document.getElementById('import_rules').value=JSON.stringify(rules); }));</script>
<script>document.addEventListener('DOMContentLoaded',function(){const form=document.querySelector('form[name="directory-import"], form[action=""]');const directory=document.getElementById('directory');const reports=document.getElementById('reports_directory');if(!directory||!reports)return;try{if(!directory.value)directory.value=localStorage.getItem('pruefapp-import-directory')||'';if(!reports.value)reports.value=localStorage.getItem('pruefapp-reports-directory')||'';}catch(_){}const save=()=>{try{localStorage.setItem('pruefapp-import-directory',directory.value);localStorage.setItem('pruefapp-reports-directory',reports.value);}catch(_){}};directory.form?.addEventListener('submit',save);reports.form?.addEventListener('submit',save);});</script>
<?php if (!empty($_GET['phoenix_job'])): ?><script>
(function(){const id=<?= json_encode((string)$_GET['phoenix_job']) ?>; const url=<?= json_encode(url_for('admin/pruefungen/import/'.rawurlencode((string)$_GET['phoenix_job']).'/status')) ?>; const poll=()=>fetch(url,{credentials:'same-origin'}).then(r=>r.json()).then(j=>{const row=document.querySelector('[data-phoenix-job="'+id+'"]');if(!row)return;row.querySelector('.job-state').textContent=j.state||'';row.querySelector('.job-progress').textContent=j.total?(j.step||0)+' / '+j.total:'—';row.querySelector('.job-device').textContent=j.current_device||'';const msg=row.querySelector('.job-message');if(msg)msg.textContent=j.message||j.error||'';if(j.state==='running'||j.state==='queued')setTimeout(poll,2000);});poll();})();
</script><?php endif; ?>
